'use strict';
const $=id=>document.getElementById(id), cfg=window.PROJECT_CONFIG;
const KEY='codexai:'+cfg.id+':v1', cats=Object.keys(cfg.budgets);
const money=n=>'¥'+(n/100).toFixed(2), today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const defaults=()=>({version:1,title:cfg.title,wish:cfg.wish,target:Math.round(cfg.target*100),opening:0,budgets:Object.fromEntries(cats.map(c=>[c,Math.round(cfg.budgets[c]*100)])),reminder:cfg.reminder,entries:[]});
function valid(s){if(!s||s.version!==1||!Array.isArray(s.entries)||s.entries.length>10000)throw Error('备份格式不正确');for(const [k,max] of [['title',24],['wish',40],['reminder',80]])if(typeof s[k]!=='string'||!s[k].trim()||s[k].length>max)throw Error('备份文字格式不正确');for(const k of ['target','opening'])if(!Number.isInteger(s[k])||s[k]<0||s[k]>100000000||(k==='target'&&s[k]===0))throw Error('备份金额不正确');if(!s.budgets||cats.some(c=>!Number.isInteger(s.budgets[c])||s.budgets[c]<0||s.budgets[c]>100000000))throw Error('预算格式不正确');const ids=new Set();for(const e of s.entries){if(!e||typeof e.id!=='string'||e.id.length>100||ids.has(e.id)||!['income','expense'].includes(e.kind)||!cats.includes(e.category)||!Number.isInteger(e.amount)||e.amount<=0||e.amount>100000000||typeof e.note!=='string'||e.note.length>60||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||Number.isNaN(Date.parse(e.date+'T12:00:00')))throw Error('记录格式不正确');ids.add(e.id);}return s;}
let state=defaults(), storageReady=true;
try{const raw=localStorage.getItem(KEY);if(raw)state=valid(JSON.parse(raw));}catch(e){storageReady=false;setTimeout(()=>tell('原有数据无法读取；请先导出或联系老师，暂不覆盖原数据。'),100);}
function tell(t){$('message').textContent=t;clearTimeout(tell.timer);tell.timer=setTimeout(()=>$('message').textContent='',6000);}
function commit(next){try{valid(next);if(!storageReady)throw Error('当前存储异常，请先联系老师处理');localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return true;}catch(e){tell('未保存：'+e.message);return false;}}
function cents(v,zero=false){if(!/^\d+(\.\d{1,2})?$/.test(String(v).trim()))throw Error('请输入最多两位小数的金额');const n=Math.round(Number(v)*100);if(!Number.isSafeInteger(n)||n<(zero?0:1)||n>100000000)throw Error('金额超出范围');return n;}
const totals=()=>state.entries.reduce((a,e)=>(a[e.kind]+=e.amount,a),{income:0,expense:0});
function render(){const t=totals(),balance=state.opening+t.income-t.expense,pct=Math.min(100,Math.max(0,balance/state.target*100));$('app-title').textContent=state.title;$('balance').textContent=money(balance);$('totals').textContent=`初始 ${money(state.opening)} · 收入 ${money(t.income)} · 支出 ${money(t.expense)}`;$('wish-name').textContent=state.wish;$('wish-percent').textContent=Math.floor(pct)+'%';$('wish-progress').value=pct;$('wish-gap').textContent=balance>=state.target?'愿望金额已达成！':`目标 ${money(state.target)} · 还差 ${money(state.target-balance)}`;for(const k of ['title','wish','reminder'])$(k).value=state[k];$('target').value=(state.target/100).toFixed(2);$('opening').value=(state.opening/100).toFixed(2);$('budgets').replaceChildren();$('budget-inputs').replaceChildren();const month=today().slice(0,7);cats.forEach((c,i)=>{const used=state.entries.filter(e=>e.kind==='expense'&&e.category===c&&e.date.startsWith(month)).reduce((a,e)=>a+e.amount,0),budget=state.budgets[c];const row=document.createElement('div');row.className='budget-row';const line=document.createElement('div'),name=document.createElement('strong'),num=document.createElement('span');name.textContent=c;num.textContent=`${money(used)} / ${money(budget)}`;line.append(name,num);const progress=document.createElement('progress');progress.max=100;progress.value=budget?Math.min(100,used/budget*100):used?100:0;progress.setAttribute('aria-label',c+'预算使用进度');row.append(line,progress);if(used>=budget){const p=document.createElement('p');p.className='muted';p.textContent=state.reminder;row.append(p);}$('budgets').append(row);const label=document.createElement('label');label.htmlFor='budget-'+i;label.textContent=c+'（元）';const input=document.createElement('input');Object.assign(input,{id:'budget-'+i,type:'number',min:'0',max:'1000000',step:'0.01',required:true,value:(budget/100).toFixed(2)});$('budget-inputs').append(label,input);});$('record-count').textContent=`共 ${state.entries.length} 笔 · 最新日期在前`;$('records').replaceChildren();if(!state.entries.length){const li=document.createElement('li');li.className='empty';li.textContent='还没有记录，从第一笔零花钱开始吧。';$('records').append(li);}state.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id)).forEach(e=>{const li=document.createElement('li'),info=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('div'),right=document.createElement('div'),amount=document.createElement('strong'),del=document.createElement('button');title.textContent=e.note||(e.kind==='income'?'零花钱收入':e.category+'支出');sub.className='muted';sub.textContent=e.date+' · '+(e.kind==='income'?'收入':e.category);info.append(title,sub);amount.className=e.kind;amount.textContent=(e.kind==='income'?'+':'−')+money(e.amount);del.textContent='删除';del.setAttribute('aria-label','删除记录 '+title.textContent+' '+e.date);del.onclick=()=>{if(confirm('删除这笔记录？余额会重新计算。')){if(commit({...state,entries:state.entries.filter(x=>x.id!==e.id)}))tell('记录已删除');}};right.append(amount,document.createElement('br'),del);li.append(info,right);$('records').append(li);});}
$('date').value=today();$('kind').onchange=()=>{$('category').disabled=$('kind').value==='income';};
$('entry-form').onsubmit=e=>{e.preventDefault();try{if(state.entries.length>=10000)throw Error('记录已达上限，请先导出备份');const item={id:crypto.randomUUID(),kind:$('kind').value,amount:cents($('amount').value),category:$('category').value,note:$('note').value.trim(),date:$('date').value};if(commit({...state,entries:[...state.entries,item]})){$('amount').value='';$('note').value='';tell('这笔记录已保存');}}catch(err){tell(err.message);}};
$('wish-form').onsubmit=e=>{e.preventDefault();try{if(commit({...state,title:$('title').value.trim(),wish:$('wish').value.trim(),target:cents($('target').value),opening:cents($('opening').value,true)}))tell('愿望已更新');}catch(err){tell(err.message);}};
$('budget-form').onsubmit=e=>{e.preventDefault();try{const budgets=Object.fromEntries(cats.map((c,i)=>[c,cents($('budget-'+i).value,true)]));if(commit({...state,budgets,reminder:$('reminder').value.trim()}))tell('预算已更新');}catch(err){tell(err.message);}};
function download(s=state){const url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='零花钱备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>download();
$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('文件过大');const next=valid(JSON.parse(await f.text()));if(confirm('使用此备份替换当前账本？确认后会先下载当前账本备份。')){download();if(commit(next))tell('备份已恢复');}}catch(err){tell('恢复失败：'+err.message);}finally{e.target.value='';}};
$('demo').onclick=()=>{if(state.entries.length&&!confirm('载入练习会替换当前记录，先下载当前备份并继续？'))return;if(state.entries.length)download();const next=defaults();next.opening=2000;next.entries=[{id:crypto.randomUUID(),kind:'income',amount:3000,category:'其他',note:'课堂练习：收到零花钱',date:today()},{id:crypto.randomUUID(),kind:'expense',amount:1200,category:'文具',note:'课堂练习：买文具',date:today()}];if(commit(next))tell('练习已载入：余额38元，愿望进度38%');};
$('reset').onclick=()=>{if(confirm('清空当前账本并恢复默认设置？会先下载当前备份。')){download();if(commit(defaults()))tell('已清空，原账本已提供备份下载');}};
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_allowance_summary',description:'读取当前设备的余额、愿望进度和记录笔数，不修改账本。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{const t=totals();return {balanceCents:state.opening+t.income-t.expense,targetCents:state.target,recordCount:state.entries.length};}})).catch(()=>{});}catch{}}

const offlineStatus=$('offline-status');
if ('serviceWorker' in navigator && window.isSecureContext) {
  navigator.serviceWorker.register('sw.js', {scope:'./'})
    .then(() => navigator.serviceWorker.ready)
    .then(() => {offlineStatus.textContent='离线页面已准备好。请从手机桌面重开，再用飞行模式试一次。';})
    .catch(() => {offlineStatus.textContent='离线页面暂未准备好，请保持联网使用。';});
} else {offlineStatus.textContent='此浏览器暂不支持离线准备，请保持联网使用。';}
